package com.hms.ui;

import com.hms.config.DatabaseConfig;
import com.hms.dao.*;
import com.hms.model.*;
import com.hms.util.*;
import javax.swing.*; import javax.swing.table.DefaultTableModel; import java.awt.*; import java.time.*; import java.util.List;

public class MainFrame extends JFrame {
 private final PatientDao patients; private final DoctorDao doctors; private final AppointmentDao appointments; private final User user;
 private final JPanel content=new JPanel(new CardLayout()); private final JLabel title=new JLabel();
 public MainFrame(User user){super("Hospital Management System");this.user=user;try{var c=new DatabaseConfig().openConnection();patients=new PatientDao(c);doctors=new DoctorDao(c);appointments=new AppointmentDao(c);}catch(Exception e){throw new IllegalStateException("Database connection failed. Check DB_* settings.",e);}setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1100,700);setLocationRelativeTo(null);build();}
 private void build(){JPanel root=new JPanel(new BorderLayout());JPanel side=new JPanel();side.setLayout(new BoxLayout(side,BoxLayout.Y_AXIS));side.setBackground(new Color(28,55,85));title.setForeground(Color.WHITE);title.setFont(title.getFont().deriveFont(Font.BOLD,16f));side.add(title);side.add(Box.createVerticalStrut(20));String[][] nav={{"Dashboard","dashboard"},{"Patients","patients"},{"Doctors","doctors"},{"Appointments","appointments"},{"Reports","reports"}};for(String[] n:nav){JButton b=new JButton(n[0]);b.setAlignmentX(Component.LEFT_ALIGNMENT);b.setMaximumSize(new Dimension(180,42));b.addActionListener(e->show(n[1]));side.add(b);}side.add(Box.createVerticalGlue());JButton logout=new JButton("Logout");logout.setAlignmentX(Component.LEFT_ALIGNMENT);logout.addActionListener(e->{dispose();try{new LoginFrame(new com.hms.service.AuthService(new UserDao(new DatabaseConfig().openConnection()))).setVisible(true);}catch(Exception x){UiUtil.error(this,x);}});side.add(logout);root.add(side,BorderLayout.WEST);root.add(content,BorderLayout.CENTER);add(root);show("dashboard");}
 private void show(String name){title.setText("  "+user.username()+" ("+user.role()+")");content.removeAll();if(name.equals("dashboard"))content.add(dashboard());if(name.equals("patients"))content.add(patientPage());if(name.equals("doctors"))content.add(doctorPage());if(name.equals("appointments"))content.add(appointmentPage());if(name.equals("reports"))content.add(reportPage());content.revalidate();content.repaint();}
 private JPanel dashboard(){JPanel p=base("Dashboard");try{JPanel cards=new JPanel(new GridLayout(1,4,12,12));cards.add(card("Patients",patients.findAll().size()));cards.add(card("Doctors",doctors.findAll().size()));cards.add(card("Today's appointments",appointments.findByFilters(LocalDate.now(),LocalDate.now(),null,null).size()));cards.add(card("Booked / pending",appointments.count("BOOKED")));p.add(cards,BorderLayout.NORTH);DefaultTableModel m=new DefaultTableModel(new String[]{"Patient","Doctor","Date","Start","Status"},0);for(Appointment a:appointments.todayAndUpcoming())m.addRow(new Object[]{a.patientName(),a.doctorName(),a.date(),a.startTime(),a.status()});p.add(new JScrollPane(new JTable(m)),BorderLayout.CENTER);}catch(Exception e){UiUtil.error(this,e);}return p;}
 private JLabel card(String label,int value){JLabel l=new JLabel("<html><center><h2>"+value+"</h2>"+label+"</center></html>",SwingConstants.CENTER);l.setBorder(BorderFactory.createLineBorder(new Color(190,200,210)));return l;}
 private JPanel patientPage(){return patientPage(null);}
 private JPanel patientPage(String query){JPanel p=base("Patients");JTextField search=new JTextField(query==null?"":query);JButton find=new JButton("Search");JButton add=new JButton("Add");JPanel top=new JPanel(new BorderLayout(5,5));top.add(search,BorderLayout.CENTER);top.add(find,BorderLayout.EAST);top.add(add,BorderLayout.WEST);p.add(top,BorderLayout.NORTH);JTable t=new JTable();try{DefaultTableModel m=new DefaultTableModel(new String[]{"ID","Name","DOB","Gender","Blood","Phone","Email","Address"},0);for(Patient x:patients.find(query)){m.addRow(new Object[]{x.id(),x.name(),x.dateOfBirth(),x.gender(),x.bloodGroup(),x.phone(),x.email(),x.address()});}t.setModel(m);}catch(Exception e){UiUtil.error(this,e);}p.add(new JScrollPane(t),BorderLayout.CENTER);JButton edit=new JButton("Edit");JButton del=new JButton("Delete");JPanel actions=new JPanel();actions.add(edit);actions.add(del);p.add(actions,BorderLayout.SOUTH);find.addActionListener(e->showPatientSearch(search.getText()));add.addActionListener(e->patientDialog(null));edit.addActionListener(e->{int r=t.getSelectedRow();if(r>=0)patientDialog((int)t.getValueAt(r,0));});del.addActionListener(e->{int r=t.getSelectedRow();if(r>=0&&JOptionPane.showConfirmDialog(this,"Delete selected patient? This may fail if appointments exist.","Confirm delete",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)try{patients.delete((int)t.getValueAt(r,0));show("patients");}catch(Exception x){UiUtil.error(this,x);}});return p;}
 private void showPatientSearch(String q){content.removeAll();content.add(patientPage(q));content.revalidate();content.repaint();}
 private void patientDialog(Integer id){JTextField name=new JTextField(),dob=new JTextField("1990-01-01"),gender=new JTextField("OTHER"),blood=new JTextField(),phone=new JTextField(),email=new JTextField(),address=new JTextField(),emergency=new JTextField();JPanel f=UiUtil.form();JComponent[] cs={name,dob,gender,blood,phone,email,address,emergency};String[] ls={"Name","DOB (YYYY-MM-DD)","Gender (MALE/FEMALE/OTHER)","Blood group","Phone","Email","Address","Emergency contact"};for(int i=0;i<ls.length;i++){f.add(new JLabel(ls[i]));f.add(cs[i]);}if(JOptionPane.showConfirmDialog(this,f,id==null?"Add patient":"Edit patient",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)try{Validation.required(name.getText(),"Name");LocalDate birth=Validation.date(dob.getText(),"DOB");if(birth.isAfter(LocalDate.now()))throw new IllegalArgumentException("DOB cannot be in the future.");Validation.email(email.getText());Validation.phone(phone.getText());String gv=gender.getText().toUpperCase();if(!List.of("MALE","FEMALE","OTHER").contains(gv))throw new IllegalArgumentException("Gender must be MALE, FEMALE, or OTHER.");Validation.required(address.getText(),"Address");Patient x=new Patient(id==null?0:id,name.getText(),birth,gv,blood.getText(),phone.getText(),email.getText(),address.getText(),emergency.getText());if(id==null)patients.save(x);else patients.update(x);show("patients");}catch(Exception e){UiUtil.error(this,e);}}
 private JPanel doctorPage(){return doctorPage("");}
 private JPanel doctorPage(String query){JPanel p=base("Doctors");JTextField q=new JTextField(query);JButton find=new JButton("Search"),add=new JButton("Add");JPanel top=new JPanel(new BorderLayout(5,5));top.add(q);top.add(find,BorderLayout.EAST);top.add(add,BorderLayout.WEST);p.add(top,BorderLayout.NORTH);JTable t=new JTable();try{DefaultTableModel m=new DefaultTableModel(new String[]{"ID","Name","Department","Specialization","Fee","Available"},0);for(Doctor d:doctors.find(query))m.addRow(new Object[]{d.id(),d.name(),d.department(),d.specialization(),d.consultationFee(),d.available()});t.setModel(m);}catch(Exception e){UiUtil.error(this,e);}p.add(new JScrollPane(t),BorderLayout.CENTER);JPanel actions=new JPanel();JButton edit=new JButton("Edit"),del=new JButton("Delete");actions.add(edit);actions.add(del);p.add(actions,BorderLayout.SOUTH);find.addActionListener(e->{content.removeAll();content.add(doctorPage(q.getText()));content.revalidate();content.repaint();});add.addActionListener(e->doctorDialog(null));edit.addActionListener(e->{int r=t.getSelectedRow();if(r>=0)doctorDialog((int)t.getValueAt(r,0));});del.addActionListener(e->{int r=t.getSelectedRow();if(r>=0&&JOptionPane.showConfirmDialog(this,"Delete selected doctor?","Confirm",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)try{doctors.delete((int)t.getValueAt(r,0));show("doctors");}catch(Exception x){UiUtil.error(this,x);}});return p;}
 private void doctorDialog(Integer id){JTextField n=new JTextField(),s=new JTextField(),dep=new JTextField(),l=new JTextField(),ph=new JTextField(),em=new JTextField(),room=new JTextField(),fee=new JTextField("0.00");JCheckBox available=new JCheckBox("Available",true);JPanel f=UiUtil.form();for(Object[] x:new Object[][]{{"Name",n},{"Specialization",s},{"Department",dep},{"License",l},{"Phone",ph},{"Email",em},{"Room",room},{"Consultation fee",fee},{"Availability",available}}){f.add(new JLabel((String)x[0]));f.add((JComponent)x[1]);}if(JOptionPane.showConfirmDialog(this,f,id==null?"Add doctor":"Edit doctor",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)try{Validation.required(n.getText(),"Name");Validation.required(s.getText(),"Specialization");Validation.required(dep.getText(),"Department");Validation.phone(ph.getText());Validation.email(em.getText());Doctor d=new Doctor(id==null?0:id,n.getText(),s.getText(),dep.getText(),l.getText(),ph.getText(),em.getText(),room.getText(),new java.math.BigDecimal(fee.getText()),available.isSelected());if(id==null)doctors.save(d);else doctors.update(d);show("doctors");}catch(Exception e){UiUtil.error(this,e);}}
 private JPanel appointmentPage(){JPanel p=base("Appointments");JButton add=new JButton("Book appointment"),reschedule=new JButton("Reschedule"),cancel=new JButton("Cancel"),complete=new JButton("Complete");JPanel actions=new JPanel();actions.add(add);actions.add(reschedule);actions.add(cancel);actions.add(complete);p.add(actions,BorderLayout.NORTH);JTable t=new JTable();try{DefaultTableModel m=new DefaultTableModel(new String[]{"ID","Patient","Doctor","Date","Start","End","Status","Notes"},0);for(Appointment a:appointments.findRecent())m.addRow(new Object[]{a.id(),a.patientName(),a.doctorName(),a.date(),a.startTime(),a.endTime(),a.status(),a.notes()});t.setModel(m);}catch(Exception e){UiUtil.error(this,e);}p.add(new JScrollPane(t),BorderLayout.CENTER);add.addActionListener(e->appointmentDialog());reschedule.addActionListener(e->{int r=t.getSelectedRow();if(r>=0)appointmentDialog((int)t.getValueAt(r,0));});cancel.addActionListener(e->appointmentStatus(t,"CANCELLED"));complete.addActionListener(e->appointmentStatus(t,"COMPLETED"));return p;}
 private void appointmentStatus(JTable t,String status){int r=t.getSelectedRow();if(r<0)return;try{Appointment a=appointments.findRecent().stream().filter(x->x.id()==(int)t.getValueAt(r,0)).findFirst().orElseThrow();appointments.update(new Appointment(a.id(),a.patientId(),a.patientName(),a.doctorId(),a.doctorName(),a.date(),a.startTime(),a.endTime(),status,a.notes()));show("appointments");}catch(Exception e){UiUtil.error(this,e);}}
 private void appointmentDialog(Integer id){JTextField pi=new JTextField(),di=new JTextField(),date=new JTextField(LocalDate.now().toString()),start=new JTextField("09:00"),end=new JTextField("09:30"),notes=new JTextField();JPanel f=UiUtil.form();for(Object[] x:new Object[][]{{"Patient ID",pi},{"Doctor ID",di},{"Date",date},{"Start time",start},{"End time",end},{"Notes",notes}}){f.add(new JLabel((String)x[0]));f.add((JComponent)x[1]);}if(JOptionPane.showConfirmDialog(this,f,"Reschedule appointment",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)try{LocalDate day=Validation.date(date.getText(),"Date");if(day.isBefore(LocalDate.now()))throw new IllegalArgumentException("Past appointment dates are not allowed.");Appointment old=appointments.findRecent().stream().filter(a->a.id()==id).findFirst().orElseThrow();appointments.update(new Appointment(id,Validation.positiveInt(pi.getText(),"Patient ID"),"",Validation.positiveInt(di.getText(),"Doctor ID"),"",day,Validation.time(start.getText(),"Start"),Validation.time(end.getText(),"End"),"BOOKED",notes.getText()));show("appointments");}catch(Exception e){UiUtil.error(this,e);}}
 private void appointmentDialog(){JTextField pi=new JTextField(),di=new JTextField(),date=new JTextField(LocalDate.now().toString()),start=new JTextField("09:00"),end=new JTextField("09:30"),status=new JTextField("BOOKED"),notes=new JTextField();JPanel f=UiUtil.form();for(Object[] x:new Object[][]{{"Patient ID",pi},{"Doctor ID",di},{"Date",date},{"Start time",start},{"End time",end},{"Status (BOOKED/COMPLETED/CANCELLED)",status},{"Notes",notes}}){f.add(new JLabel((String)x[0]));f.add((JComponent)x[1]);}if(JOptionPane.showConfirmDialog(this,f,"Book appointment",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)try{LocalDate day=Validation.date(date.getText(),"Date");if(day.isBefore(LocalDate.now()))throw new IllegalArgumentException("Past appointment dates are not allowed.");LocalTime st=Validation.time(start.getText(),"Start time"),en=Validation.time(end.getText(),"End time");if(!en.isAfter(st))throw new IllegalArgumentException("End time must be after start time.");String v=status.getText().toUpperCase();if(!List.of("BOOKED","COMPLETED","CANCELLED").contains(v))throw new IllegalArgumentException("Invalid appointment status.");appointments.save(new Appointment(0,Validation.positiveInt(pi.getText(),"Patient ID"),"",Validation.positiveInt(di.getText(),"Doctor ID"),"",day,st,en,v,notes.getText()));show("appointments");}catch(Exception e){UiUtil.error(this,e);}}
 private JPanel reportPage(){JPanel p=base("Reports");JTextField from=new JTextField(),to=new JTextField(),doctor=new JTextField();JComboBox<String> status=new JComboBox<>(new String[]{"ALL","BOOKED","COMPLETED","CANCELLED"});JButton run=new JButton("Run report");JPanel filters=new JPanel(new GridLayout(2,4));filters.add(new JLabel("From YYYY-MM-DD"));filters.add(from);filters.add(new JLabel("To YYYY-MM-DD"));filters.add(to);filters.add(new JLabel("Status"));filters.add(status);filters.add(new JLabel("Doctor ID"));filters.add(doctor);p.add(filters,BorderLayout.NORTH);JTextArea out=new JTextArea();out.setEditable(false);p.add(new JScrollPane(out),BorderLayout.CENTER);run.addActionListener(e->{try{LocalDate f=from.getText().isBlank()?null:Validation.date(from.getText(),"From date"),t=to.getText().isBlank()?null:Validation.date(to.getText(),"To date");String st=status.getSelectedItem().equals("ALL")?null:(String)status.getSelectedItem();Integer d=doctor.getText().isBlank()?null:Validation.positiveInt(doctor.getText(),"Doctor ID");List<Appointment> rows=appointments.findByFilters(f,t,st,d);StringBuilder b=new StringBuilder("Appointments: ").append(rows.size()).append("\\n");for(Appointment a:rows)b.append(a.date()).append(" ").append(a.startTime()).append(" - ").append(a.patientName()).append(" / ").append(a.doctorName()).append(" [").append(a.status()).append("]\\n");out.setText(b.toString());}catch(Exception x){UiUtil.error(this,x);}});p.add(run,BorderLayout.SOUTH);return p;}
 private JPanel base(String n){JPanel p=new JPanel(new BorderLayout(10,10));p.setBorder(BorderFactory.createEmptyBorder(15,15,15,15));p.add(new JLabel(n),BorderLayout.NORTH);return p;}
}
